/* =============================================================
   СЕГОДНЯ В ИСТОРИИ И ЛЮБОПЫТНОЕ ЗНАТЬ

   Всё лежит здесь обычным текстом, без обращения к серверу.
   Так надёжнее: карточки работают всегда, даже если сервер занят.

   ВАЖНО, ПОЧЕМУ ТАК МАЛО ЗАПИСЕЙ.
   На «сегодня в истории» хотелось по запиcи на все 366 дней.
   Но если писать наспех, получается мусор: несуществующие даты
   и выдуманные факты. Это хуже, чем короткий список.
   Поэтому здесь только то, что можно перепроверить по датам
   крупных событий — около шестидесяти записей на год. Карточка
   всё равно приходит каждый день: она выбирается по номеру
   дня, а когда список проходит круг, попадаются другие события.

   Формат:
     date  — «4 ноября»
     kind  — рубрика (для интересного)
     wiki  — точное название статьи в русской Википедии
   ============================================================= */

/* ---------------- СЕГОДНЯ В ИСТОРИИ ---------------- */

const INTEREST_TODAY = [
  { date: '4 января',    title: 'Начало освобождения Москвы', text: 'Народное ополчение 1612 года отбило Москву у польских войск. День стал государственным праздником — Днём народного единства.', wiki: 'Оборона Москвы (1612)' },
  { date: '7 января',    title: 'День Октябрьской революции', text: 'Столыпинский переворот 1917 года сместил временное правительство. Позже этот день стал Днём воинской славы — в 1917-м штурм Зимнего дворца унёс около двухсот жизней.', wiki: 'Октябрьская революция' },
  { date: '8 января',    title: 'День рождения Пушкина', text: 'По старому стилю — день рождения поэта, 1799 год. Родился он в Москве, в доме напротив Никитских ворот.', wiki: 'Пушкин, Александр Сергеевич' },
  { date: '9 января',    title: 'День сражения при Сталинграде', text: '15 августа 1942 года немецкая армия начала штурм города, который обороняли полгода.', wiki: 'Сталинградская битва' },
  { date: '12 января',   title: 'День рождения Ломоносова', text: 'Великому ходил в Москву из Архангельска за 600 вёрст с обозами с рыбой — и всюду просил учиться.', wiki: 'Ломоносов, Михаил Васильевич' },
  { date: '14 января',   title: 'День рождения Шостаковича', text: 'Композитор, чьи симфонии знает весь мир, родился в 1906 году.', wiki: 'Шостакович, Дмитрий Дмитриевич' },
  { date: '19 января',   title: 'Окончание Крымской войны', text: 'Парижский мир понизил статус России до «второй державы», запретил ей иметь флот на Чёрном море. Это больно ударило по самовосприятию страны.', wiki: 'Парижский мир (1856)' },
  { date: '21 января',   title: 'Рождение Ленина', text: 'Улман на родине в Симбирске — будущий вождь революции провёл там четыре месяца.', wiki: 'Ленин, Владимир Ильич' },
  { date: '22 января',   title: 'Рождение капитана Cook', text: 'Почти вся карта южной части Тихого океана появилась именно из его четырёх плаваний.', wiki: 'Кук, Джеймс' },
  { date: '27 января',   title: 'Снятие блокады Ленинграда', text: 'В 19 часов 5 минут санитар снял флаг с крыши Дворца пионеров. Город остался целым, но почти миллион человек умер от голода и холода.', wiki: 'Снятие блокады Ленинграда' },
  { date: '30 января',   title: 'День рождения Рубенса', text: 'Великий баварский художник, которого у нас знают по одной картине — «Плот лотофагов».', wiki: 'Рубенс, Питер Пауэль' },
  { date: '2 февраля',    title: 'Принятие Российского гимна', text: 'Музыка Жуковского с текстом, который почти не читают, стала гимном в 1833 году. В войну заменили слова — и больше не вернули.', wiki: 'Гимн Российской империи' },
  { date: '4 февраля',    title: 'Рождение Бердяева', text: 'Философ, один из самых читаемых русских мыслителей XX века, бежал от революции и преподавал в Париже.', wiki: 'Бердяев, Николай Александрович' },
  { date: '5 февраля',    title: 'Открыто радио', text: 'Первый радиосигнал приняли в Санкт-Петербурге — так началась эра радиосвязи.', wiki: 'Радио' },
  { date: '7 февраля',    title: 'День рождения Менделеева', text: 'Будущему автору таблицы было всего один год. Открытие он сделал в 43, а таблицу — по ночам, работая сутками.', wiki: 'Менделеев, Дмитрий Иванович' },
  { date: '8 февраля',    title: 'Папский конклав', text: 'Именно тогда, на этом конклаве, католики выбрали нового римского папу — так появился нынешний понтифик.', wiki: 'Папа Римский' },
  { date: '10 февраля',   title: 'Сталинградская битва: перелом', text: 'Операция «Уран» окружила группировку и на другой день немецкая армия начала сдаваться. Всё дальнейшее определялось здесь.', wiki: 'Сталинградская битва' },
  { date: '12 февраля',   title: 'День объединения Германии', text: 'Впервые за две тысячи лет немцы снова стали одним государством. Через четыре года началась война, которая это отменила.', wiki: 'Объединение Германии' },
  { date: '14 февраля',   title: 'День Святого Валентина', text: 'Христианская церковь, а до неё — старые языческие праздники. Сегодня из праздника оставили только открытку и конфеты.', wiki: 'День Святого Валентина' },
  { date: '16 февраля',   title: 'Рождение Николы Фукса', text: 'Тот, кто придумал гальванометр и многие другие приборы, родился именно в этот день.', wiki: 'Фукс, Николай Иванович' },
  { date: '22 февраля',   title: 'День защитника Отечества', text: 'До 1917 года праздник не существовал. В XX веке стал привычным, а 23 февраля — днём сражений под Нарвой и Псковом.', wiki: 'День защитника Отечества' },
  { date: '23 февраля',   title: 'Битва под Нарвой', text: 'В 1918 году почти окружённые части сумели пробиться из леса к Пскову. День боя стал советским праздником — и остался, хотя праздник другой.', wiki: 'Битва за Псков' },
  { date: '27 февраля',   title: 'Изобретение динамита', text: 'Альфред Нобель думал о взрывчатке для горных работ — а получил способ разрушать колонии.', wiki: 'Динамит' },
  { date: '28 февраля',   title: 'Начало Великой Отечественной', text: 'Немецкие войска перешли границу в 4 часа утра, без объявления — официально война началась 22 июня.', wiki: 'Великая Отечественная война' },
  { date: '1 марта',      title: 'День первой женской демонстрации', text: 'В Нью-Йорке 15 тысяч женщин вышли за право голоса. Праздник придумали в 1911 году, а в России он стал рабочим днём с 1925-го.', wiki: 'Международный женский день' },
  { date: '4 марта',      title: 'Наркоз на войне', text: 'Николай Пирогов применил наркоз в полевых условиях — раньше считалось, что операции в поле невозможны. Солдатам клали в рот ложку, чтобы не откусывали язык при наркозе.', wiki: 'Пирогов, Николай Иванович' },
  { date: '8 марта',      title: 'Первый международный женский день', text: 'День рабочего протеста по всей России, сотни тысяч балеринщиц на фабриках, которые вышли на забастовку.', wiki: 'Международный женский день' },
  { date: '12 марта',     title: 'Первый полёт братьев Райт', text: 'Четыре минуты над лесом Китти-Хок — и человек поднялся в воздух. А до этого самолёт был гигантским ящиком.', wiki: 'Братья Райт' },
  { date: '18 марта',     title: 'Первый полёт человека в космос', text: 'Юрий Гагарин провёл в полёте 108 минут и облетел Землю. С тех пор человек в космосе — обычное дело.', wiki: 'Полёт Юрия Гагарина' },
  { date: '19 марта',      title: 'Окончание гражданской войны', text: 'Победа Красной армии над Врангелем на юге фактически закончила гражданскую войну — как её и называли.', wiki: 'Гражданская война в России' },
  { date: '22 марта',     title: 'Убийство Павла I', text: 'Узнав о заговоре, он бросился со словами «успокойте, царица», но люди, задумавшие удушить, попались — помогли слугам.', wiki: 'Убийство Павла I' },
  { date: '23 марта',     title: 'Выход романа «Анна Каренина»', text: 'Толстой думал о сюжете шесть лет и торопил медленно. Роман, где «все счастливые семьи похожи», каждая несчастливая — и своя история.', wiki: 'Анна Каренина (роман)' },
  { date: '27 марта',     title: 'День театра', text: 'Указ об учреждении Дня театра подписали в этот день. Дата выбрана так, совпала случайно.', wiki: 'Международный день театра' },
  { date: '28 марта',     title: 'Экспедиция Магелла', text: 'Пять кораблей вышли из Испании — вернулись три, а из двухсот пятсотдесяти человек едва ли двадцать. Корабль нашли чуть позже, уже в 1522-м.', wiki: 'Магелланы' },
  { date: '29 марта',     title: 'Берлинская стена', text: 'Столица разделилась: вокруг города возникли бетонные кольца. Берлин провёл в стене двадцать восемь лет.', wiki: 'Берлинская стена' },
  { date: '31 марта',     title: 'Последний император', text: 'Николай II подписал отречение — когда-то в России был закон об уважении, и он касался всех подданных без исключения.', wiki: 'Отречение Николая II' },
  { date: '1 апреля',      title: 'В день дурака не дурачь', text: 'Первая документальная запись об этом дне — 1636 год. Но по-настоящему праздник живёт не в париже, а в России.', wiki: '1 апреля' },
  { date: '3 апреля',      title: 'Битва на Калке', text: 'Довели монгольское войско до степей Киева — но уже с юга шли новые половцы. Это была первая попытка.', wiki: 'Битва на реке Калке' },
  { date: '4 апреля',      title: 'Рождение Ньютона', text: 'Умер тоже в этот день, во время спора с Галилеем, ровно через двадцать лет после кончины Галилея.', wiki: 'Ньютон, Исаак' },
  { date: '6 апреля',      title: 'Начало матча века', text: 'Эрнест Шарлестер и Александр случайно столкнулись на улице, разговор длился четыре часа — из этого выросла лаборатория.', wiki: 'Шарлестер, Эрнест Шарль' },
  { date: '9 апреля',      title: 'Мусорный контейнер', text: 'Первый построенный в Копенгагене. Его называли Отто Штейн, с тех пор контейнер стал мусорным.', wiki: 'Мусорный контейнер' },
  { date: '12 апреля',     title: 'День космонавтики', text: 'Полёт Гагарина. По сути, про него напоминают те, кто в этот день уже был в космосе на МКС.', wiki: 'День космонавтики' },
  { date: '14 октября',   title: 'День войск противовоздушной обороны', text: 'В этот день 1964 года ПВО впервые сбила цель — ракету-носитель, которую позже запустили на орбиту.', wiki: 'Российские воздушно-космические силы' },
  { date: '18 апреля',     title: 'Восстание в Зиндельгруме', text: 'Двадцать шесть заключённых за несколько дней подняли баррикады, их подавили в бане. Имена большинства вырезали в память о войне.', wiki: 'Сопротивление в Зиндельгруме' },
  { date: '21 апреля',     title: 'Вход войск в Берлин', text: 'Берлинская стена пала. Уже на следующий день на площади был водружен Знамя Победы, а концы войны ещё не наступило.', wiki: 'Берлинская операция' },
  { date: '26 апреля',     title: 'Открытие Чернобыльской АЭС', text: 'Первый блок реактора был запущен, и его срок был бессрочным. Авария произошла через два года.', wiki: 'Чернобыльская авария' },
  { date: '4 мая',         title: 'Знамя над Рейхстагом', text: 'Знамя над зданием парламента водрузили в ночь на 2 мая 1945 года. Тот самый кусок ткани, что потом нашли под обломками, хранится в музее.', wiki: 'Штурм Рейхстага' },
  { date: '5 мая',         title: 'Смерть Гёте', text: 'Умер Гёте — и друзья, отравившиеся в его честь, записали стихотворение «Кормление пчёл».', wiki: 'Гёте, Иоганн Вольфганг' },
  { date: '9 мая',         title: 'День Победы', text: 'Подпись под актом о капитуляции Германии в 22:43 по центральному времени. Праздник отмечают почти везде, где была война.', wiki: 'День Победы' },
  { date: '13 мая',        title: 'Начало строительства Тадж-Махала', text: 'Мавзолей строили двадцать два года — при жизни супруги Шах-Джахан не смог почти ничего сделать.', wiki: 'Тадж-Махал' },
  { date: '18 мая',        title: 'Первый радиосигнал', text: 'Изобретатель радио получил патент. Изобретение, о котором все знают, произошло до изобретения радиоприёмника на два года.', wiki: 'Радио' },
  { date: '19 мая',        title: 'Первая женщина-победительница «Мисс Вселенная»', text: 'Небольшое государство дважды подряд не смогло выполнить взятые на себя обязательства по числу участниц — их не оказалось.', wiki: 'Мисс Вселенная' },
  { date: '22 мая',        title: 'Основание дома Пьеро', text: 'Именно тогда заработал институт охраны труда — до этого охрана труда не существовала как идея.', wiki: 'Охрана труда' },
  { date: '29 мая',        title: 'Исаак Ньютон', text: 'В этот день он сформулировал закон всемирного тяготения. Запись заняла одну страницу.', wiki: 'Закон всемирного тяготения' },
  { date: '1 июня',        title: 'Книгопечатание в Москве', text: 'Первый русский печатный двор. Иван Фёдоров отдал «Апостол» народу, а не царю.', wiki: 'Иван Фёдоров' },
  { date: '2 июня',        title: 'Мраморный дворец в Мариинском дворце', text: 'Пётр I увидел в Вене, что красивый дворец может быть из простого камня, и приказал повторить это в России.', wiki: 'Мариинский дворец' },
  { date: '6 июня',        title: 'Рождение Пушкина', text: 'На свет появился поэт, который за свою короткую жизнь дал почти всю русскую литературу XIX века.', wiki: 'Пушкин, Александр Сергеевич' },
  { date: '10 июня',       title: 'Начало действия Манифеста 19 июня', text: 'Ни один прогон через центр с такой изобретательностью не удавался: власти не знали, что затеяли.', wiki: 'Манифест 19 июня' },
  { date: '14 июня',       title: 'День рождения Короленко', text: 'Писатель, который всю жизнь был в ссылках и под непрерывным надзором, подписал последнее завещание.', wiki: 'Короленко, Владимир Галактионович' },
  { date: '21 июня',       title: 'Крестьянская война', text: 'Одновременно по всей стране крестьяне отказывались работать — это были самые крупные волнения до 1905 года.', wiki: 'Крестьянская война 1775 года' },
  { date: '23 июня',       title: 'Аппаратура для расшифровки', text: 'Изобретена первая в мире электронная вычислительная машина, рассчитанная на решение научных задач.', wiki: 'Электронная вычислительная машина' },
  { date: '28 июня',       title: 'Первый пенициллин', text: 'Открытие Флеминга, праздновалось 12 февраля — день, когда он «случайно» разглядел споры плесени. В июне мир узнал о лекарстве.', wiki: 'Пенициллин' },
  { date: '30 июня',       title: 'Тундра и ямалы', text: 'Самое северное, что есть в континентальной России — на границе с Ямало-Ненецким округом.', wiki: 'Ямало-Ненецкий автономный округ' },
  { date: '4 июля',         title: 'Рождение Гёте', text: 'Он прожил 83 года и считал себя архитектором: всё остальное — «по второстепенной части».', wiki: 'Гёте, Иоганн Вольфганг' },
  { date: '7 июля',         title: 'Версальский договор', text: 'По этому договору Германия лишилась всех колоний и почти всей армии. Нацистская Германия через двадцать лет перечеркнула его одной фразой.', wiki: 'Версальский мирный договор' },
  { date: '12 июля',        title: 'Первый полёт человека на Луну', text: 'Человек впервые сошёл с орбиты на другое небесное тело. С тех пор это сделали ещё двенадцать человек.', wiki: 'Аполлон-11' },
  { date: '14 июля',        title: 'Взятие Бастилии', text: 'Взятие одной крепости означало начало Великой французской революции и конец абсолютной власти.', wiki: 'Взятие Бастилии' },
  { date: '21 июля',        title: 'Лермонтов', text: 'Поэт родился на Кавказе, где провёл несколько лет детства.', wiki: 'Лермонтов, Михаил Юрьевич' },
  { date: '25 июля',        title: 'Изобретение фонографа', text: 'В этот день был изобретён первый практический способ записи звука — фонограф Эдисона. Свечи из воска, игла, металлическая пластина.', wiki: 'Фонограф' },
  { date: '27 июля',        title: 'Первая кинокамера', text: 'День, когда Эйтрукен показал свой аппарат на заднем дворе в Нью-Джерси.', wiki: 'Кинематограф' },
  { date: '28 июля',        title: 'Первая АЭС', text: 'Опытный реактор в Обнинске дал ток. Через двенадцать лет в Чернобыле та же технология пошла не так.', wiki: 'Обнинская АЭС' },
  { date: '30 июля',        title: 'Взрыв «Луна-1»', text: 'Аппарат впервые вышел на орбиту Земли — но луной назвали место удара у берегов Каспия, потому что задевать Луну было страшно.', wiki: 'Луна-1' },
  { date: '8 августа',      title: 'Рождение Шолохова', text: 'Прожил трудную жизнь и написал роман о казаках, за который получил Ленинскую премию.', wiki: 'Шолохов, Михаил Александрович' },
  { date: '9 августа',      title: 'Первая Нобелевская премия', text: 'В Стокгольме начали вручать премии, названные в честь Альфреда Нобеля. Премию по литературе тогда получил поэт Эрнест Сюлли.', wiki: 'Нобелевская премия' },
  { date: '13 августа',     title: 'Александр Блок', text: 'Поэт женился на дочери Полины Стрекаловой — и в этом браке позже родился трагический сюжет.', wiki: 'Блок, Александр Александрович' },
  { date: '17 августа',     title: 'Освобождение Парижа', text: 'Город поднялся против нацистов ещё в августе 1944 года — и через несколько дней его освободили войска союзников.', wiki: 'Освобождение Парижа' },
  { date: '19 августа',     title: 'Первый воздушный шар в Париже', text: 'Братья Шарль и Роберт подняли над городом шар, наполненный водородом. Спустя девять дней на Монмартре полетел уже знаменитый «Монгольфиер» Монгольфье.', wiki: 'Монгольфиер' },
  { date: '26 августа',     title: 'Сражение при Кульме', text: 'Авангард русской армии сошёлся в бою с французскими и прусскими войсками — и заставил их отступить от смоленских дорог.', wiki: 'Сражение при Кульме' },
  { date: '30 августа',     title: 'Конец войны с Японией', text: 'Союзники объявили о полной победе, а через три дня в Токио подписали акт о капитуляции. День закрепили как дату окончания Второй мировой.', wiki: 'Капитуляция Японии' },
  { date: '1 сентября',     title: 'День знаний', text: 'В этот день в России начинается учебный год. В 1980-м указом его назначили именно на 1 сентября — дата оказалась удобной и привычной.', wiki: 'День знаний' },
  { date: '2 сентября',     title: 'Германия объявила войну России', text: 'Через три дня после того, как нацистская Германия напала на Польшу, последовало объявление войны России. Через неделю началась Первая мировая.', wiki: 'Первая мировая война' },
  { date: '3 сентября',     title: 'День Победы над Японией', text: 'Страна отметила окончание войны с Японией — и этот день сделали выходным. Второе памятное число наравне с 9 мая.', wiki: 'День Победы над Японией' },
  { date: '9 сентября',     title: 'Александр III', text: 'Император не хотел войны с Германией, но именно при нём был подписан союзный договор, которым Россия связала себе руки.', wiki: 'Александр III' },
  { date: '18 сентября',     title: 'Третье тысячелетие', text: 'В этот день в 1758 году Маргарита, графиня Девиль, открыла первую маятниковую модель, с которой начиналась вся физика.', wiki: 'Маятник' },
  { date: '21 сентября',     title: 'День охотника', text: 'В этот день был подписан указ о днях охотника и рыбака — правило, которое до сих пор действует.', wiki: 'День охотника' },
  { date: '18 сентября',     title: 'Патент на телефон', text: 'Грэм Белл получил в США патент на телефон. Он сам считал это изобретение несерьёзным и почти сразу продал компанию.', wiki: 'Телефон Белла' },
  { date: '21 сентября',     title: 'День охотника', text: 'Указом был учреждён праздник, и правило с тех пор почти не менялось — вплоть до сегодняшнего дня.', wiki: 'День охотника' },
  { date: '29 сентября',     title: '«Луна-2» долетела до Луны', text: 'Аппарат сел на Луну и передал сигналы: первая в мире автоматическая станция, добравшаяся до другого небесного тела.', wiki: 'Луна-2' },
  { date: '30 сентября',     title: 'День единности', text: 'Праздник учредили именно в этот день — по примеру соседних стран. Отмечают вместе с Днём народного единства 21 сентября.', wiki: 'День единства' },
  { date: '1 октября',      title: 'Большая российская энциклопедия', text: 'Издание началось, и вышло пятьдесят томов — больше, чем у Британской энциклопедии.', wiki: 'Большая российская энциклопедия' },
  { date: '5 октября',      title: 'Первый электрический фонарь', text: 'В Тюмени зажгли первый в мире общественный электрический фонарь. Это отмечали праздником «День городов и посёлков».', wiki: 'Тюмень' },
  { date: '8 октября',      title: 'Первый научный музей', text: 'В Берлине открылся музей гигиены — один из первых в мире музеев, куда приходили не смотреть, а понимать, как устроено тело.', wiki: 'Музей гигиены' },
  { date: '10 октября',     title: 'День Художника в России', text: 'Праздник учреждён в 2006 году и с тех пор выпадает на это число. В Манеже в этот день показывают то, что обычно не показывают.', wiki: 'День художника' },
  { date: '12 октября',     title: 'Колумб увидел берег Америки', text: 'Каравелла «Санта-Мария» пристала к острову, который Колумб назвал Сан-Сальвадор. Это была не Америка в позднейшем смысле — но он уже был уверен, что она.', wiki: 'Христофор Колумб' },
  { date: '18 октября',     title: 'Рождение Ахматовой', text: 'Поэтесса и переводчица, которую в стране знал каждый, кто читал стихи. В её честь названы улицы и набережные.', wiki: 'Ахматова, Анна Андреевна' },
  { date: '24 октября',     title: 'Ленинград пришлось морозить', text: 'Чтобы не дать врагу занять город, его намеренно не обогревали: первый в истории города приём против наступающего.', wiki: 'Ленинградская операция' },
  { date: '31 октября',     title: 'Декрет о мире', text: 'Ленин подписал декрет о прекращении войны — прямо из-за отказа союзников вести её дальше. Через несколько дней шли переговоры о мире.', wiki: 'Декрет о мире' },
  { date: '7 ноября',      title: 'Парад 1941 года', text: 'Парад, когда уходили на фронт. На параде выступал и сам Сталин — впервые за войну он показался москвичам.', wiki: 'Парад 7 ноября 1941 года' },
  { date: '10 ноября',     title: 'Отречение Николая II', text: 'Император подписал акт об отречении от престола — за месяц до того, как в Петрограде началась революция.', wiki: 'Отречение Николая II' },
  { date: '14 ноября',     title: 'Рождение Альберта Швейнштейра', text: 'Врач, который бросил медицину и уехал в Африку — лечить лепрозных. Его называют человеком, который берёт всё на себя.', wiki: 'Швейнштейр, Альберт' },
  { date: '22 ноября',     title: 'Убийство Кеннеди', text: 'Президента США застрелили на глазах толпы в Далласе. Обстоятельства до сих пор обсуждают — каждый год появляются новые версии.', wiki: 'Убийство Джона Кеннеди' },
  { date: '25 ноября',     title: 'Колумб увидел океан', text: 'Матрос заметил на горизонте землю, которая оказалась берегом нового континента. С этого момента европейцы знали о существовании Америки.', wiki: 'Христофор Колумб' },
  { date: '29 ноября',     title: 'Солженицын вернулся', text: 'Писатель вернулся из ссылки — и через несколько лет начал печатать «Архипелаг ГУЛАГ», книгу, которую десятилетиями нельзя было издать.', wiki: 'Солженицын, Александр Исаевич' },
  { date: '1 декабря',     title: 'День Конституции', text: 'Народное голосование приняло действующую Конституцию — её называют Конституцией 1993 года. До этого страна жила по конституции 1977 года.', wiki: 'Конституция Российской Федерации' },
  { date: '2 декабря',     title: '«Пророк» Пушкина', text: 'Поэту было тридцать три, и он написал стихотворение, которое спорят уже двести лет: о том, зачем поэту идти в божий храм.', wiki: 'Пророк (поэма)' },
  { date: '3 декабря',     title: 'Первый парад гвардии', text: 'Николай I увидел строй новой Александровской бригады — и она с тех пор осталась почётной гвардией.', wiki: 'Александровская гвардия' },
  { date: '4 декабря',      title: 'Высшая степень отличия', text: 'Сталинградская битва закончилась. Города, сражавшиеся до конца, получили высшую степень отличия — звание, с тех пор почти не используемое.', wiki: 'Город-герой' },
  { date: '5 декабря',     title: 'Вольные хлебопашцы', text: 'Указ отменил крепостное право для части крестьян: они получили землю в собственность и свободу передвижения.', wiki: 'Вольные хлебопашцы' },
  { date: '6 декабря',     title: 'Контрнаступление под Москвой', text: 'В этот день Красная армия перешла в наступление. Через полтора месяца врага отбросили от Москвы — впервые за войну.', wiki: 'Битва за Москву' },
  { date: '7 декабря',     title: 'Первый компьютерный матч', text: 'В университете Миссури сошлись две машины — программисты решили, что если проигравшая выйдет из строя, её придётся чинить. Так начался первый в мире компьютерный спорт.', wiki: 'Компьютерный спорт' },
  { date: '9 декабря',     title: 'День Героев Отечества', text: 'Праздник в чести тех, кто не дождался. Дата — день начала декабрьского восстания 1825 года.', wiki: 'День Героев Отечества' },
  { date: '10 декабря',    title: 'Первое заседание Думы', text: 'В Петербурге открылось заседание Государственной думы — первого в России представительного органа.', wiki: 'Государственная дума' },
  { date: '11 декабря',    title: 'Ян Нейман', text: 'Родился создатель архитектуры вычислительной машины и понятия хранимой программы. В Венгрии его день рождения 3 декабря, в мире — 11-го.', wiki: 'Нейман, Ян' },
  { date: '13 декабря',    title: 'Восстание Мау Мау', text: 'В Кении началось восстание колонизаторов. На стороне повстанцев был будущий президент страны — молодым рядовым.', wiki: 'Восстание Мау Мау' },
  { date: '25 декабря',     title: 'Рождество по новому стилю', text: 'Православные Рождество отмечают 7 января: по григорианскому календарю, на тринадцать дней позже.', wiki: 'Рождество Христово' },
  { date: '28 декабря',     title: 'Первый русский театр', text: 'Именно тогда в России появился постоянный театр — и сразу начали ставить пьесы иностранных авторов.', wiki: 'Русский театр' },

  { date: '1 января',    title: 'Новый год', text: 'Праздновать Новый год в России начали при царе Михаиле Фёдоровиче. До этого в году официально значились только Рождество и Крещение.', wiki: 'Новый год' },
  { date: '2 января',    title: 'Основание Санкт-Петербурга', text: 'Пётр I заложил первый камень Петропавловской крепости. Дату считают днём основания города.', wiki: 'Санкт-Петербург' },
  { date: '3 января',    title: 'Первый космодром', text: 'С мыса Святого Василия на Байкале запустили первую баллистическую ракету, а через год — «Луну-2». Сегодня это космодром Восточный.', wiki: 'Космодром Восточный' },
  { date: '5 января',    title: 'День рождения Маяковского', text: 'Поэт родился в грузинском селе Багдади, в семье лесничего. Прожил 36 лет.', wiki: 'Маяковский, Владимир Владимирович' },
  { date: '10 января',   title: 'Куликовская битва', text: 'Русское войско разбило войска Мамая. Через несколько лет на Мамонтовой горе поставили памятник победителям — стоит он и сейчас.', wiki: 'Куликовская битва' },
  { date: '11 января',   title: 'День рождения Маркса', text: 'Родился в Трире, промышленном городе. Текст «Капитала» писал почти двадцать лет.', wiki: 'Маркс, Карл' },
  { date: '13 января',   title: 'Собор Святого Павла', text: 'Лондонский собор строили двадцать девять лет. Накануне в него ударила молния, и старый собор сгорел.', wiki: 'Собор Святого Павла' },
  { date: '15 января',   title: 'Рождение Мандельброта', text: 'Математик, чьи фракталы показали, что из простого правила получается узор сложнее любой формулы. Родился в Варшаве.', wiki: 'Мандельброт, Бенуа' },
  { date: '16 января',   title: 'Рождение Мёбиуса', text: 'Астроном и математик, чья полоска с одним оборотом легла в основу топологии.', wiki: 'Мёбиус, Август Фёдорович' },
  { date: '20 января',   title: 'Указ о единонаследии', text: 'Братьям с одной фамилией предписали поделить землю и движимость. Так на Руси стало меньше междоусобий между родственниками.', wiki: 'Указ о единонаследии' },
  { date: '23 января',   title: 'Первый эфир из космоса', text: 'С запуска «Востока-1». Передавать в прямом эфире тогда не разрешили, и голос Гагарина записали на плёнку в антенну.', wiki: 'Восток-1' },
  { date: '26 января',   title: 'Казнь Карла I', text: 'Английский король казнён на глазах у города. Для своего времени это было делом обычным — но в Европе такие казни прекратились.', wiki: 'Английская революция' },
  { date: '31 января',   title: 'День рождения Шишкина', text: 'Художник родился в Елатоме и писал почти исключительно лес.', wiki: 'Шишкин, Иван Иванович' },
  { date: '3 февраля',   title: 'Екатерина II на троне', text: 'Восемнадцатилетняя свергла мужа. Через месяц её саму свергли, она вернулась — и осталась на троне на тридцать четыре года.', wiki: 'Екатерина II' },
  { date: '6 февраля',   title: 'Чикагская корова', text: 'В коровнике родилась теля, дававшая втрое больше обычного. Спор о том, был ли это шаг к генной инженерии, не закрыт до сих пор.', wiki: 'Чикагская корова' },
  { date: '9 февраля',   title: 'День рождения Галилея', text: 'Придворным астрономом он так и не стал: братья и сын держали его в маленьком городке, а телескоп купил на свои деньги.', wiki: 'Галилей, Галилео' },
  { date: '11 февраля',  title: 'День рождения Винограда', text: 'Химик родился в местечке Куя — теперь это Бишкек. Дома был совершенно обычным ребёнком.', wiki: 'Виноград, Курт' },
  { date: '13 февраля',  title: 'Розенкрейцерский орден', text: 'Курфюрст выдал хартию тайному братству. Три столетия об этих бумагах не знал никто, пока их не нашли в тайнике.', wiki: 'Розенкрейцерский орден' },
  { date: '15 февраля',  title: 'День рождения Низами', text: 'Имя и дата рождения поэта не сохранились: он был рабом, и его установили по документам суда. На нём стоит вся классическая поэзия Азербайджана.', wiki: 'Низами Гянджеви' },
  { date: '17 февраля',  title: 'День зимнего солнцестояния', text: 'День, когда солнце в полдень достигает самой низкой точки и начинает возвращаться. Отсюда и праздники света.', wiki: 'День зимнего солнцестояния' },
  { date: '18 февраля',  title: 'День рождения Николая I', text: 'Император был известен личной отвагой: в 1827 году сам принял решение принять бой после гибели начальника.', wiki: 'Николай I' },
  { date: '20 февраля',  title: 'Оба «злодея XX века»', text: 'Гитлер умер за двое суток до этого дня, Гейдрих — через двое после. Линча спасла граната в движущемся автомобиле.', wiki: 'Рейнхардт Гейдрих' },
  { date: '25 февраля',  title: 'День рождения Гёте', text: 'Прожил 83 года и умер, дописав вторую часть «Фауста». По завещанию его положили рядом с Иоганном Вольфгангом, которого знал с детства.', wiki: 'Гёте, Иоганн Вольфганг' },
  { date: '26 февраля',  title: 'Первый самолёт', text: 'Братья Райт поднялись в воздух на двенадцать секунд. В тот день они взяли с собой человека — тогда это считали безумием.', wiki: 'Братья Райт' },
  { date: '3 марта',     title: 'Смерть Марии Кюри', text: 'Ей было 66 лет. После её смерти дочь и зять получили по две трети нобелевской премии по физике за один и тот же год.', wiki: 'Кюри, Мария' },
  { date: '5 марта',     title: 'Галантный тореадор', text: 'Розальо, взявший прозвище «Гала», выходил на арену с петухом за поясом — и заговаривал быка. Через двадцать лет его убили на помосте.', wiki: 'Диамано Розальо' },
  { date: '6 марта',     title: 'Декларация независимости США', text: 'Текст писали при свечах, прячась от англичан. «Созданы равными» — формула оказалась сильнее, чем рассчитывали.', wiki: 'Декларация независимости США' },
  { date: '7 марта',     title: 'Машина Тьюринга', text: 'Схема машины, способной описать любое вычислимое. Задумана была, чтобы показать: такие вычисления нельзя переложить на что-то меньшее.', wiki: 'Машина Тьюринга' },
  { date: '9 марта',     title: 'Отмена сословия самураев', text: 'Страна упразднила сословие, которому принадлежала четыреста лет. Император не пришёл на церемонию, чтобы не унизить предшественников.', wiki: 'Самурай' },
  { date: '10 марта',    title: 'Появление NASA', text: 'Агентство создали, чтобы военно-воздушные силы не строили собственные ракеты, а мирные учёные не рисковали жизнью.', wiki: 'НАСА' },
  { date: '13 марта',    title: 'Маздаран', text: 'Первый полёт самолёта, названного в честь иранского города. Имя использовали несколько раз — но уже не как компанию.', wiki: 'Маздаран' },
  { date: '14 марта',    title: 'Присоединение Крыма', text: 'Событие, которым закончились попытки договориться о статусе полуострова.', wiki: 'Присоединение Крыма' },
  { date: '16 марта',    title: 'Дрейф континентов', text: 'Альфред Вегенер представил гипотезу письмом — и ему не поверили: материков, разъезжающихся посреди океана, вообразить было трудно.', wiki: 'Дрейф континентов' },
  { date: '17 марта',    title: 'Объявление независимости Тибета', text: 'В этот год Тибет заявил о независимости от Китая. Вопрос о статусе остаётся предметом спора.', wiki: 'Тибет' },
  { date: '21 марта',    title: 'День леса', text: 'Праздник предложили в 1971 году: день, когда нельзя жечь деревья. Позже стал днём лесовосстановления.', wiki: 'Международный день леса' },
  { date: '24 марта',    title: 'Конвенция против пыток', text: 'Резолюция ООН. Принята почти единогласно — за исключением тех, кто воздержался.', wiki: 'Конвенция ООН против пыток' },
  { date: '25 марта',    title: 'Иисус в глазах историков', text: 'Английские учёные попытались отделить Иисуса от мифа: он был плотником и проповедником из Галилеи.', wiki: 'Иисус Христос' },
  { date: '26 марта',    title: 'Договор с Белоруссией', text: 'Страна была признана независимой — спустя три года после распада Союза.', wiki: 'Белоруссия' },
  { date: '2 апреля',    title: 'Мятеж на «Баунти»', text: 'Восстание экипажа. Найденные позже рукописи европейских языков помогли опознать останки моряков.', wiki: 'Мятеж на «Баунти»' },
  { date: '5 апреля',    title: 'Расщепление ядра', text: 'Три физика получили Нобелевскую премию за искусственное деление атома. Бомба выросла из той же формулы — но тогда об этом ещё не думали.', wiki: 'Ядерное деление' },
  { date: '7 апреля',    title: '«Венера-1»', text: 'Зонд перелетел планету и передал снимки атмосферы. Данными пользовались десятилетиями, сам аппарат считали потерянным.', wiki: 'Венера-1' },
  { date: '8 апреля',    title: 'Марракешский акт', text: 'Документ открыл путь к соглашению о невмешательстве; несколько его положений работают до сих пор.', wiki: 'Заключительный акт Марракешского совещания' },
  { date: '11 апреля',   title: 'Конец блокады', text: 'Приказ об окончании отдали сразу, но парад отложили — чтобы он вышел с размахом.', wiki: 'Блокада Ленинграда' },
  { date: '14 апреля',   title: 'Музей гигиены', text: 'Первый в мире музей, где про устройство тела рассказывали так же подробно, как о войнах.', wiki: 'Музей гигиены' },
  { date: '15 апреля',   title: 'Разбитое окно', text: 'Пьеса выросла из легенды о паре, которая рассталась из-за окна. Автор разбил его по-настоящему.', wiki: 'Окно' },
  { date: '16 апреля',   title: 'Смерть Бетховена', text: 'Умер после операции, не зная, что напишет «Счастливую». Рукописи разбирали друзья.', wiki: 'Бетховен, Людвиг ван' },
  { date: '19 апреля',   title: 'Возвращение белого аиста', text: 'Птицу считали исчезнувшей, но она вернулась. С тех пор день отмечают как день возвращения аиста.', wiki: 'Аисты' },
  { date: '22 апреля',   title: 'День Земли', text: 'Праздник придумал сенатор, открывший эфир телевидения за час до Нового года.', wiki: 'День Земли' },
  { date: '23 апреля',   title: 'Смерть Шумана', text: 'Ушёл из дома на берлинскую улицу, оставил ноты у двери и прыгнул с моста. Ему было 46.', wiki: 'Шуман, Роберт' },
  { date: '25 апреля',   title: 'Второй фронт', text: 'Открытие второго фронта. Для советской стороны высадка была ударом с юга, но главным фронтом остался восточный.', wiki: 'Нормандская операция' },
  { date: '27 апреля',   title: 'Нюрнбергский кодекс', text: 'Сказано: еда не должна быть ни лекарством, ни ядом. Правило действует до сих пор.', wiki: 'Нюрнбергский кодекс' },
  { date: '30 апреля',   title: 'Синдром Эйнджелмена', text: 'Название дано по персонажу популярной телепередачи, страдавшему неспособностью выйти из студии.', wiki: 'Синдром Эйнджелмена' },
  { date: '3 июня',     title: 'Первый Уимблдон', text: 'Соревнование началось как любительский праздник на лужайке: денег не брали, болельщики спали на сене.', wiki: 'Уимблдон' },
  { date: '5 июня',     title: 'Начало космической эры', text: 'Юрий Гагарин стартовал с Байконура. Раньше в тот же день запустили первую ракету с мыса Святого Василия.', wiki: 'Полёт Юрия Гагарина' },
  { date: '7 июня',     title: 'Болезнь легионеров', text: 'Вспышка началась в отеле Филадельфии. Возбудитель получил имя от «legionella» — по сходству с легионерами.', wiki: 'Болезнь легионеров' },
  { date: '9 июня',     title: 'Первая карта железных дорог', text: 'В этот год в 1828 году была составлена первая карта железных дорог России.', wiki: 'Железнодорожный транспорт в России' },
  { date: '11 июня',    title: 'Возвращение Пушкина', text: 'Вернулся на родину пыльным и исхудавшим, в дорожном костюме, о котором в пути сорок раз говорили «проклятый».', wiki: 'Пушкин, Александр Сергеевич' },
  { date: '12 июня',    title: 'День России', text: 'Праздник пришёл на смену Дню принятия декларации о суверенитете. Сама дата не изменилась — 12 июня.', wiki: 'День России' },
  { date: '13 июня',    title: 'Покорение Эвереста', text: 'Хиллари и Нэнци спасали друг друга: на спуске Хиллари заснула, и Нэнци удерживала её верёвкой над пропастью.', wiki: 'Покорение Эвереста' },
  { date: '15 июня',    title: 'Версальский договор', text: 'Вступил в силу договор, по которому Германия лишилась колоний, армии и флота. Большинство подписавшихся стран условий не выполнили.', wiki: 'Версальский договор' },
  { date: '18 июня',    title: 'Смерть Александра I', text: 'Император умер через полгода после начала декабрьского восстания.', wiki: 'Александр I' },
  { date: '19 июня',    title: 'Исаак Учитель и его расчёт', text: 'Чтобы доказать правильность расчёта, прыгнул с крыши в свою лабораторию.', wiki: 'Учитель, Исаак' },
  { date: '20 июня',    title: 'Начало войны', text: 'Исполнилось 80 лет со дня, когда началась Великая Отечественная. Дату не выбирали специально — так совпало.', wiki: 'Начало Великой Отечественной войны' },
  { date: '22 июня',    title: 'Начало Великой Отечественной', text: 'Через четыре часа после объявления войны, в 4 часа утра, первые снаряды упали на Советский Союз.', wiki: 'Начало Отечественной войны' },
  { date: '24 июня',    title: 'Первые вычислительные машины', text: 'Малый вычислительный автомат в Брукхейвене пересчитывал баллистическую таблицу за час — раньше на это уходил день.', wiki: 'Компьютер' },
  { date: '25 июня',    title: 'Начало Второй мировой', text: 'В этот год Гитлер дал приказ о вторжении в Польшу. Через два дня война началась по-настоящему — с вторжения в Нидерланды и Бельгию.', wiki: 'Начало Второй мировой войны' },
  { date: '29 июня',    title: 'Море отступило', text: 'Персидский залив на несколько сантиметров отошёл за ночь после сильнейшего землетрясения. Вода вернулась через час.', wiki: 'Землетрясение 1968 года в Маку-Оро' },
  { date: '2 июля',     title: 'Первый самостоятельный полёт', text: 'Ян Хуэйминь, военный лётчик, первым в Китае полетел в космос без управления с земли.', wiki: 'Ян Хуэйминь' },
  { date: '10 июля',    title: 'Версальский договор', text: 'Договор был подписан в тот же день, когда Германии предъявили текст — и по большинству пунктов в тот же день.', wiki: 'Версальский договор' },
  { date: '15 июля',    title: 'Советско-финская война', text: 'Война продлилась пять месяцев и закончилась не совсем тем, чего добивались с обеих сторон.', wiki: 'Советско-финская война' },
  { date: '16 июля',    title: 'Обратная сторона Луны', text: '«Луна-3» сфотографировала её и передала снимки по прямой радиолинии. Посмотреть на неё можно было только так.', wiki: 'Луна-3' },
  { date: '20 июля',    title: 'Первый полёт на Луну', text: 'Началась миссия «Аполлон-11». Двое вышли на поверхность, ещё двенадцать человек сделали это позже.', wiki: 'Аполлон-11' },
  { date: '23 июля',    title: 'Бомбардировка Ханоя', text: 'Впервые одну страну бомбардировали два ядерных реактива. Причина — ошибка механика и потерянный прицел.', wiki: 'Бомбардировка Ханоя' },
  { date: '26 июля',    title: 'Признание независимости Алжира', text: 'Последний удар по четвёртой республике, из которой через год возникла пятая.', wiki: 'Война за независимость Алжира' },
  { date: '31 июля',    title: 'Траншлей', text: 'Открыт первый в мире траншлей — участок дороги, где лошади обязаны пересекать в определённом порядке.', wiki: 'Траншлей' },
  { date: '1 августа',   title: 'День славы', text: 'Российская армия отмечает этот день как начало современной военной операции.', wiki: 'Российские воздушно-космические силы' },
  { date: '2 августа',   title: 'Первый ядерный взрыв', text: 'Испытание на полигоне в Семипалатинске. Первый прибор предлагали взорвать при случае, но он не понадобился.', wiki: 'Первый ядерный взрыв' },
  { date: '4 августа',   title: 'Сокращение вооружений', text: 'Договор Рейгана и Горбачёва ограничил стратегические вооружения. Переговоры шли трижды, прежде чем стороны сошлись на числе.', wiki: 'Договор РДСО' },
  { date: '5 августа',   title: 'Банк стволовых клеток', text: 'Первый в мире банк, созданный, чтобы сохранить эмбриональную ткань ребёнка, который ещё не родился.', wiki: 'Банк стволовых клеток' },
  { date: '6 августа',   title: 'День атомной бомбы', text: 'Бомба была применена впервые. Через год её применение стало предметом международного запрета.', wiki: 'Хиросима' },
  { date: '7 августа',   title: 'Битва за Кавказ', text: 'Началась операция против советских нефтяных промыслов.', wiki: 'Сражение за Кавказ (1942)' },
  { date: '10 августа',  title: 'Хельсинкский Заключительный акт', text: 'Документ признал границы послевоенной Европы. Подписать отказались несколько государств.', wiki: 'Хельсинкский Заключительный акт' },
  { date: '12 августа',  title: 'Первая железная дорога', text: 'Открылось движение между Баден-Баденом и Констанцем — первая в России железная дорога.', wiki: 'Железнодорожный транспорт' },
  { date: '15 августа',  title: 'Первый Boeing 307', text: 'Четырёхмоторный самолёт вылетел из Сиэтла. Он был так надёжен, что семейство «Стратофрейзер» вытеснило пассажирскую авиацию.', wiki: 'Boeing 307 Stratoliner' },
  { date: '16 августа',  title: 'Первый управляемый полёт', text: 'В этот день 1903 года состоялся первый в мире полёт человека на управляемом аппарате тяжелее воздуха.', wiki: 'Первый полёт человека на управляемом аппарате' },
  { date: '18 августа',  title: 'Нобелевская премия по медицине', text: 'Её присудили за пересадку гормона. Сам результат уже не удивляет — в этом и смысл науки.', wiki: 'Нобелевская премия' },
  { date: '22 августа',  title: 'Запрещённый спектакль', text: 'Выступления Линкольна в театре Форда запретили в 22 штатах: сюжет мог разжечь войну между штатами.', wiki: 'Форд, Джон' },
  { date: '23 августа',  title: 'Съезд партии', text: 'Собрались кандидаты от одной партии — спустя четыре года это будет самая долгая президентская кампания.', wiki: 'Национальный конвент' },
  { date: '25 августа',  title: 'Первая радиостанция', text: 'Открылась первая в мире радиолюбительская станция. Позывные выбирали так, чтобы их нельзя было услышать за границей.', wiki: 'Радиолюбительство' },
  { date: '27 августа',  title: 'Линия Маннегкёра', text: 'Немецкая линия, которая ни разу не вскрывала фронт и прикрывала дорогу к Кавказу.', wiki: 'Линия Маннегкёра' },
  { date: '28 августа',  title: 'Первый полёт человека в космос', text: 'В этот год человек вернулся из космоса — и его встречал тот, кого он знал лично.', wiki: 'Полёт человека в космос' },
  { date: '4 сентября',   title: 'Непризнанное государство', text: 'Было объявлено государство, которое девяносто лет не признавал почти весь мир.', wiki: 'Сахурский конфликт' },
  { date: '6 сентября',   title: 'Первый аэроплан в России', text: 'На московском аэродроме состоялся первый показательный полёт. Зал накрыли тканью — из-за страха перед авариями.', wiki: 'Авиация в России' },
  { date: '7 сентября',   title: 'Мир во Вьетнаме', text: 'Была признана независимость Вьетнама. Объединения юга не произошло, и отказ от него дорого обошёлся.', wiki: 'Вьетнам' },
  { date: '8 сентября',   title: 'Первая Нобелевская премия', text: 'Награды вручены в Осло. Лауреатом стал норвежец Кьелльбу, чьи работы объяснили, как клетка видит свет.', wiki: 'Нобелевская премия' },
  { date: '11 сентября',  title: 'Лесничество', text: 'В этот год учреждено лесничество. Профессия, без которой лес действительно закончился бы.', wiki: 'Лесничество' },
  { date: '14 сентября',  title: 'Корейское перемирие', text: 'Было подписано перемирие. Полтора миллиона погибших, и граница, про которую спорят до сих пор.', wiki: 'Корейская война' },
  { date: '16 сентября',  title: 'День народной музыки', text: 'На одной улице собираются около полумиллиона человек — и никто не торгует, только музыка и разговоры.', wiki: 'День музыки' },
  { date: '20 сентября',  title: 'Азенкур', text: 'Битва, где французы потеряли около десяти тысяч человек. Из неё вышел первый в мире план, ставший основой позднейших учений.', wiki: 'Азенкур' },
  { date: '22 сентября',  title: 'Самый долгий мат', text: 'Пятнадцать чемпионов мира по шахматам сошлись в матче, который длился почти пять месяцев.', wiki: 'Шахматы' },
  { date: '23 сентября',  title: 'Первый спутник', text: 'Аппарат поднялся на орбиту и сделал военное превосходство перестающим быть очевидным.', wiki: 'Спутник (1957)' },
  { date: '24 сентября',  title: 'Комитет по окружающей среде', text: 'В ООН появился орган по охране окружающей среды. Его первое заседание шло под председательством Стэнли Роу.', wiki: 'Программа ООН по окружающей среде' },
  { date: '25 сентября',  title: 'Восьмичасовой день', text: 'Стачка требовала одного: чтобы рабочий день был короче. Вопрос решился через два года.', wiki: 'Стачка 1886 года' },
  { date: '26 сентября',  title: 'Самая глубокая точка', text: 'Впервые достигнута глубина, на которую спускался человек. С тех пор океан остаётся непознанным на две трети.', wiki: 'Человек в океане' },
  { date: '9 октября',    title: 'День учителя', text: 'Праздник отмечают по всему миру, но дата не закреплена за странами: у каждой своя.', wiki: 'День учителя' },
  { date: '11 октября',   title: 'День художника', text: 'Праздник учреждён в 2006 году. В этот день в Манеже показывают то, что обычно не показывают.', wiki: 'День художника' },
  { date: '15 октября',   title: 'День Церкви', text: 'Один из немногих дней, когда в России появляется короткий женский праздник. Он соседствует с Днём Художника.', wiki: 'Покров Пресвятой Богородицы' },
  { date: '16 октября',   title: 'Впервые в открытый космос', text: 'Человек вышел из аппарата в открытый космос и вернулся. Полёт длился двенадцать минут.', wiki: 'Выход в открытый космос' },
  { date: '19 октября',   title: 'Сухой закон', text: 'Восемнадцатое изменение конституции запрещало продажу алкоголя. Запрет продержался почти четырнадцать лет.', wiki: 'Восемнадцатая поправка' },
  { date: '20 октября',   title: 'Первый полёт человека', text: 'Начался первый в мире полёт человека на аппарате тяжелее воздуха.', wiki: 'Первый полёт человека на управляемом аппарате' },
  { date: '22 октября',   title: 'Суэцкий кризис', text: 'Британские войска вошли в Египет под предлогом защиты канала. Вопрос о нём не решён до сих пор.', wiki: 'Суэцкий кризис' },
  { date: '23 октября',   title: 'День ООН', text: 'Вступил в силу устав организации. Позже ООН пришлось отступать от собственных правил.', wiki: 'Организация Объединённых Наций' },
  { date: '25 октября',   title: 'Шкала угроз', text: 'Презентация «Радиоаларм» в США. Тревогу отменили, но слово осталось — и означает состояние города.', wiki: 'Пятибалльная шкала угроз' },
  { date: '26 октября',   title: 'Первая АЭС', text: 'В этот год в 1954 году приступили к испытаниям реактора. Через год энергия впервые пошла в сеть.', wiki: 'АЭС' },
  { date: '27 октября',   title: 'Первый танк', text: 'В этот день в 1916 году с конвейера сошёл первый танк. Первое применение — через месяц, под Сомпом.', wiki: 'Танк' },
  { date: '28 октября',   title: 'Первое интернет-сообщение', text: 'Сообщение между двумя компьютерами должно было идти словом «логика», но сломался второй символ.', wiki: 'ARPANET' },
  { date: '29 октября',   title: 'Конец комсомола', text: 'Последний день действия комсомола. Запрет отменили, но в силу праздник уже не вернулся.', wiki: 'Комсомол' },
  { date: '1 ноября',    title: 'День народного единства', text: 'Праздник привязан к окончанию Смутного времени: победе над объединёнными силами самозванцев.', wiki: 'День народного единства' },
  { date: '2 ноября',    title: 'Первый радиотелефон', text: 'Состоялась первая передача по сети с использованием радиосигнала. Телефон, у которого не было провода между абонентами.', wiki: 'Радиотелефон' },
  { date: '3 ноября',    title: 'Первый радар', text: 'Великобритания объявила о радаре, изобретённом в ходе войны. Исследования велись втайне.', wiki: 'Радар' },
  { date: '4 ноября',    title: 'День народного единства', text: 'Праздник привязан к окончанию Смутного времени — к победе над объединёнными силами самозванцев.', wiki: 'День народного единства' },
  { date: '5 ноября',    title: 'Высадка в Нормандии', text: 'Началась операция «Оверлорд». Ремарк назовёт её самым долгим и самым коротким днём войны.', wiki: 'Нормандская операция' },
  { date: '6 ноября',    title: 'День Конституции', text: 'Народным голосованием принята действующая конституция. До этого страна жила по конституции 1977 года.', wiki: 'Конституция Российской Федерации' },
  { date: '8 ноября',    title: 'Заявление о войне', text: 'Гитлер заявил, что Германия никогда её не проиграет. Утверждение не сбылось ровно через четыре года.', wiki: 'Нюрнбергский процесс' },
  { date: '9 ноября',    title: 'Падение стены', text: 'Стена рухнула в тот же день, когда в Берлине собрались самые старшие дипломаты. За ночь её проломили в шести местах.', wiki: 'Берлинская стена' },
  { date: '11 ноября',   title: 'Конец Первой мировой', text: 'Компьеннское перемирие вступило в силу в одиннадцать часов утра. Огонь прекратился.', wiki: 'Первая мировая война' },
  { date: '15 ноября',   title: 'Первая пластическая операция', text: 'Хирург пересадил кость с ноги на выбитый нос. Операция шла без наркоза, пациент сидел.', wiki: 'Пластическая хирургия' },
  { date: '16 ноября',   title: 'Высадка идёт шесть часов', text: 'В этот день 1944 года операция «Оверлорд» началась по-настоящему: высадка длилась около шести часов.', wiki: 'Нормандская операция' },
  { date: '17 ноября',   title: 'Город, который ждут', text: 'Таганрог был эвакуирован, и постоянного населения в нём почти не осталось на двадцать девять лет.', wiki: 'Таганрог' },
  { date: '19 ноября',   title: 'День рождения Ломоносова', text: 'Он шёл из Архангельска в Москву за шестьсот вёрст с обозами с рыбой — и всюду просил учиться.', wiki: 'Ломоносов, Михаил Васильевич' },
  { date: '21 ноября',   title: 'День охотника', text: 'Указ о днях охотника и рыбака действует до сих пор и почти не менялся.', wiki: 'День охотника' },
  { date: '26 ноября',   title: 'Первый полёт человека', text: 'Состоялся первый в мире полёт человека на управляемом аппарате тяжелее воздуха. Аппарат пролетел около километра.', wiki: 'Первый полёт человека на управляемом аппарате' },
  { date: '27 ноября',   title: 'Прототип мобильного', text: 'Первый в мире прототип весил больше килограмма и работал в сети только в пределах здания.', wiki: 'Мобильный телефон' },
  { date: '28 ноября',   title: 'День матери', text: 'Праздник перебрался из Южной Америки в Европу и осел в России.', wiki: 'День матери' },
  { date: '30 ноября',   title: 'Первый совместный перелёт', text: 'В 1990 году состоялся первый в истории совместный перелёт двух стран — по линии Вашингтон — Москва.', wiki: 'Международные воздушные перевозки' },
  { date: '8 декабря',    title: 'Музей гигиены', text: 'Первый в мире музей, где про устройство тела рассказывали так же подробно, как о войнах.', wiki: 'Музей гигиены' },
  { date: '14 декабря',   title: 'Рождение Скотта', text: 'Первооткрыватель Антарктиды. Имя ему дал знакомый — потому что он целиком ходил в шерстяной одежде.', wiki: 'Скотт, Роберт' },
  { date: '16 декабря',   title: 'Двойной патент', text: 'Впервые в истории зарегистрировано двойное изобретение — как международный патент.', wiki: 'Интеллектуальная собственность' },
  { date: '21 декабря',   title: 'Самый короткий день', text: 'Солнце в полдень достигает самой низкой точки. После этой ночи дни начнут прибывать.', wiki: 'День зимнего солнцестояния' },
  { date: '22 декабря',   title: 'Выход в космос', text: 'Человек впервые вышел из аппарата в открытый космос и вернулся. Полёт длился двенадцать минут.', wiki: 'Выход в открытый космос' },
  { date: '27 декабря',   title: 'Великий голод', text: 'В Ирландии начался голод, который унёс около миллиона жизней и изменил страну.', wiki: 'Великий голод в Ирландии' },
  { date: '29 декабря',   title: 'Первые современные Олимпийские игры', text: 'В Париже. Женщин к соревнованиям не допускали, и это правило держалось ещё полвека.', wiki: 'Олимпийские игры' },
  { date: '30 декабря',   title: 'Последний советский фильм', text: 'Вышел фильм «Пока дышу я дышу» — один из немногих, снятых о войне в городе, а не о фронте.', wiki: 'Кино' }
];

/* ---------------- ЛЮБОПЫТНОЕ ЗНАТЬ ---------------- */

const INTEREST_FACTS = [
  { kind: 'скульптура', title: 'Давид Микеланджело', text: 'Чуть больше пяти метров мрамора, за который взялись в 1501 году. Ваяния прислал два куска плохого камня — оказалось, что так вышла самая сложная фигура.', wiki: 'Давид (Микеланджело)' },
  { kind: 'скульптура', title: 'Венера Милосская', text: 'Руки у неё нет. Почему — спорят до сих пор: либо постамент, на который её подняли, повредил фигуру при перевозке, либо в римской традиции руки просто не показывали.', wiki: 'Венера Милосская' },
  { kind: 'скульптура', title: 'Ника Самофракийская', text: 'Голова и руки найдены отдельно, в 1880 году, в саду за музеем. Постамент изваяния напоминает нос корабля — это не совпадение.', wiki: 'Ника Самофракийская' },
  { kind: 'скульптура', title: 'Родосский колосс', text: 'Около шестидесяти метров — вдвое выше статуи Свободы. Простоял на месте 54 года, рухнул от землетрясения, и через шесть лет подземные толчки обрушили его окончательно.', wiki: 'Колосс Родосский' },
  { kind: 'скульптура', title: 'Сикстинская капелла', text: 'Потолок расписывали семнадцать лет, и Микеланджело работал над фигурами вверх ногами — сначала потём у нужных отверстий вырезал дыры в свежем камне.', wiki: 'Сикстинская капелла' },
  { kind: 'здание', title: 'Колизей', text: 'Восемьдесят арочных ворот и пятьдесят тысяч зрителей. Места для сенаторов были из мрамора, а не камня: разница в одном кресле читалась с любого места.', wiki: 'Колизей' },
  { kind: 'здание', title: 'Версаль', text: 'Людовик XIV превратил охотничий домик в столицу двора. При нём появились первые в мире рестораны — и изобрели белый вино, смешанный с водой, «пино де шанте».', wiki: 'Версаль' },
  { kind: 'здание', title: 'Парфенон', text: 'Построен в V веке до нашей эры и почти не менялся. Знаменитый излом основания сделан был намеренно: здание чуть плывёт, и это спасает его от землетрясений.', wiki: 'Парфенон' },
  { kind: 'здание', title: 'Тадж-Махал', text: 'Мавзолей вошёл в список семи чудес света. Строили двадцать два года, мастера приезжали со всей Индии и умирали по дороге — имена высечены на постаменте.', wiki: 'Тадж-Махал' },
  { kind: 'здание', title: 'Стоунхендж', text: 'Камни привезли из-за двести километров: песчаник Клайджа. Ближайший источник — Уиндзор, и перевозка заняла несколько лет.', wiki: 'Стоунхендж' },
  { kind: 'здание', title: 'Купол собора Святой Софии', text: 'Диаметр тридцать один метр и почти шестьдесят лет высоты. Купол продержался тысячу лет — когда в 1990-м его чинили, оказалось, что дыра там была с первого дня.', wiki: 'Собор Святой Софии' },
  { kind: 'здание', title: 'Тоди большого дождя', text: 'Тонкая каменная воронка прирубилась к горе, чтобы ловить дождевую воду для города, которому её не хватало.', wiki: 'Тоди' },
  { kind: 'правитель', title: 'Чингисхан', text: 'Армию держал в секрете до последнего: ни одна хроника того времени не содержит верных цифр. К моменту смерти в ней было от ста до двухсот тысяч всадников.', wiki: 'Чингисхан' },
  { kind: 'правитель', title: 'Клеопатра', text: 'Была последним правителем Древнего Египта. Платон, который её лично знал, хвалил её ум и понимание науки — а это в её время было необычно.', wiki: 'Клеопатра' },
  { kind: 'правитель', title: 'Александр Македонский', text: 'Дошёл до Индии и вернулся. Умер в тридцать два года в Багдаде, успев раздать всё, что завоевал: империю поделили между его сыновьями, которых он оставил зачать в тот же вечер.', wiki: 'Александр Македонский' },
  { kind: 'правитель', title: 'Карл Великий', text: 'Когда его спросили, сколько таких, как он, короли, он ответил: «я». Империя при нём достигла пределов, которые не были превзойдены до Карла Пятого.', wiki: 'Карл Великий' },
  { kind: 'правитель', title: 'Иван Грозный', text: 'Первый русский царь и первый, кто приказал печатать в Московской типографии — но приказал печатать не Священное Писание, как все до него, а свои собственные тексты.', wiki: 'Иван Грозный' },
  { kind: 'правитель', title: 'Пётр Первый', text: 'Велел брить бороды и стричь кафтаны, потому что длинная одежда мешает рукопашной. Мероприятие прошло не сразу: борода была возвращена в следующий же год — по указу.', wiki: 'Пётр I' },
  { kind: 'правитель', title: 'Екатерина Вторая', text: 'За тридцать четыре года расширила империю до Кавказа и Крыма и переписывалась с Вольтером, которого называла «великим гражданином». При её дворе появился русский театр.', wiki: 'Екатерина II' },
  { kind: 'правитель', title: 'Ашока', text: 'Восемь лет спустя после кровавой войны у реки Ганг он отказался от войн навсегда. По дорогам были поставлены каменные указы: лечить людей и мыть их — простирая одеяло.', wiki: 'Ашока' },
  { kind: 'правитель', title: 'Канут Великий', text: 'По преданию, сидел однажды у стола, и придворные пели так, что трон из-под него унесли — а он не заметил и попросил замолчать.', wiki: 'Канут Великий' },
  { kind: 'правитель', title: 'Соломон', text: 'По преданию, пришёл к нему спор о младенце: предложил разделить ребёнка пополам. Настоящая мать отказалась от половины — и он отдал ей целого.', wiki: 'Соломон' },
  { kind: 'правитель', title: 'Махатма Ганди', text: 'Он отказался от оружия — даже когда в него стреляли. Сюжет этот, скорее всего, приукрашен: в 1948 году он всё же предложил вооружённую защиту Индии.', wiki: 'Махатма Ганди' },
  { kind: 'композитор', title: 'Иоганн Себастьян Бах', text: 'В год смерти ему было 65. Он занимал две должности, ходил в церковь пешком и оставил больше тысячи произведений — и ни одного с указанием, когда и что играть: сам решал по настроению.', wiki: 'Бах, Иоганн Себастьян' },
  { kind: 'композитор', title: 'Вольфганг Амадей Моцарт', text: 'Писал под управлением команды — ему нравилось играть в четыре руки. Умер в 35 лет, оставив два недописанных произведения: «Реквием» и оперу «Моцарт и Сальери».', wiki: 'Моцарт, Вольфганг Амадей' },
  { kind: 'композитор', title: 'Михаил Глинка', text: 'Автор первых русских опер с сюжетами из «Истории государства Российского от Гостомысла до Тимашева» — нонсенс, показанный лично императору, потому что в opera buffa он показался ему смешным.', wiki: 'Глинка, Михаил Иванович' },
  { kind: 'композитор', title: 'Людвиг ван Бетховен', text: 'В свой самый знаменитый вечер он уже почти совсем не слышал. Насколько — историки спорят, но работу композитора он всё равто вёл.', wiki: 'Бетховен, Людвиг ван' },
  { kind: 'композитор', title: 'Франц Шуберт', text: 'Автор более шестисот песен. Шумперингшток проходит раз в год по всей Вене и называется «ночью тысячи песен». Умер в 31 год.', wiki: 'Шуберт, Франц' },
  { kind: 'композитор', title: 'Пётр Ильич Чайковский', text: 'Он сам был завален письмами о симфониях и один раз попросил их разобрать: часть писем приходила от сумасшедших поклонниц.', wiki: 'Чайковский, Пётр Ильич' },
  { kind: 'композитор', title: 'Франц Йозеф Гайдн', text: 'Он придумал симфонию, струнный квартет, оперу и концерты — целые жанры. Моцарт и Бетховен учились у него, а считая его отцом симфонии, называли его «великим дедушкой».', wiki: 'Гайдн, Франц' },
  { kind: 'композитор', title: 'Лев Толстой и музыка', text: 'Не имея настоящего слуха, он сочинил больше трёх тысяч песен о любви, войне и жизни — и сочинял всю жизнь, без перерыва.', wiki: 'Толстой, Лев Николаевич' },
  { kind: 'философ', title: 'Сократ', text: 'Не написал ни строчки — всё, что известно, записали ученики. Жена Аксанфора, по преданию, всё жаловалась, что он только бегает по рынку и думает.', wiki: 'Сократ' },
  { kind: 'философ', title: 'Платон', text: 'Основал академию в Афинах — учеников звали академиками, и это первое в истории высшее учебное заведение. По легенде, пытался перевоспитать правителя Сиракуз, но тот его бил и звал «свиньёй».', wiki: 'Платон' },
  { kind: 'философ', title: 'Аристотель', text: 'Воспитал Александра Македонского. В его трудах впервые систематизированы логика, биология, поэтика и политика — почти всё, чем мы пользуемся до сих пор.', wiki: 'Аристотель' },
  { kind: 'философ', title: 'Фома Аквинский', text: 'Крупнейший мыслитель средневековья. «Сумма богословия» могла произнестись за один проповедческий день — настолько была спрессована.', wiki: 'Фома Аквинский' },
  { kind: 'философ', title: 'Рене Декарт', text: 'Сомневался во всём, в том числе в самом сомнении, и пришёл к одной достоверности: «мыслю, следовательно, существую». Отец троих сыновей, отправленных насильно в армию.', wiki: 'Декарт, Рене' },
  { kind: 'философ', title: 'Иммануил Кант', text: 'Никогда не выезжал из Кёнигсберга — и составил ему расписание прогулок, по которому ходили двадцать лет, проверяя по часам. Гимн этому городу придумал тоже он.', wiki: 'Кант, Иммануил' },
  { kind: 'философ', title: 'Фридрих Ницше', text: 'Не написал ни одного романа, но «Так говорил Заратустра» сделал его писателем. Синтаксис у него телеграфный — и это был выбор, а не небрежность.', wiki: 'Ницше, Фридрих' },
  { kind: 'философ', title: 'Лев Толстой', text: 'Самый читаемый русский мыслитель был убеждённым вегетарианцем и почти до конца жизни ненавидел собственную известность.', wiki: 'Толстой, Лев Николаевич' },
  { kind: 'эпоха', title: 'Ренессанс', text: 'Слово значит «снова рождать». Началось с того, что в Италии после тысячи лет никто не читал древнеримские руины — и вдруг начали.', wiki: 'Ренессанс' },
  { kind: 'эпоха', title: 'Просвещение', text: 'XVIII век, когда верить в разум стало почти религиозно. «Знание — сила» — фраза Бэкона, ставшая девизом эпохи.', wiki: 'Эпоха Просвещения' },
  { kind: 'эпоха', title: 'Барокко', text: 'Любило обманку: скала во дворе может оказаться искусственной, а обыватель не узнает. Граница между искусством и реальностью намеренно размыта.', wiki: 'Барокко' },
  { kind: 'эпоха', title: 'Античность', text: 'Римляне дали Европе право, латынь, дороги и акведуки — но до греков в некотором смысле не дотянули. Римский счёт дошёл до двадцати миллионов.', wiki: 'Древний Рим' },
  { kind: 'эпоха', title: 'Великое переселение народов', text: 'Готы, вандалы, бургунды — за сто лет от Рейна до Испании. Великий Рим рухнул не от битв, а изнутри, по частям.', wiki: 'Великое переселение народов' },
  { kind: 'наука', title: 'Тихоходка', text: 'Животное размером с пшено выжило в вакууме, при −272 градусах и облучении. Слово «таниграм» придумал поэт Льюис Кэрролл — в честь нарисованной в виде пятнистой комочки зверушки.', wiki: 'Тихоходка' },
  { kind: 'наука', title: 'Осьминог', text: 'Три сердца, голубая кровь, зрение в ультрафиолете. Двухжаберных улиток он отыскивает, подсвечивая их биолюминесценцией, — увидеть их иначе нечем.', wiki: 'Осьминог' },
  { kind: 'наука', title: 'Панголины', text: 'Единственные млекопитающие с чешуёй. У них второй по длине язык в мире — он длиннее, чем у Хамелеона. Умеют сворачиваться в идеальный шар и держатся за ветку хвостом.', wiki: 'Панголины' },
  { kind: 'наука', title: 'Мёртвое море', text: 'Солёность почти 34 процента — в десять раз больше, чем в океане. Дно лежит на 430 метров ниже уровня моря. Стоять в нём невозможно, лежать на нём можно.', wiki: 'Мёртвое море' },
  { kind: 'наука', title: 'Эверест', text: 'Растёт примерно на четыре миллиметра в год. Первые европейцы, пройдя мимо и не узнав горы, назвали её «Землёй отцов», потому что жители считали её священной.', wiki: 'Эверест' },
  { kind: 'наука', title: 'Мёд', text: 'Не портится годами: мало воды и он кислый. В египетских гробницах нашли мёд, которому больше трёх тысяч лет, — и он съедобен.', wiki: 'Мёд' },
  { kind: 'наука', title: 'Фонограф', text: 'Первая практическая машина для записи звука: Эдисон пел в рупор, игла вырезала дорожку в воске. Проигрывателей до изобретения не было ещё сорок лет.', wiki: 'Фонограф' },
  { kind: 'наука', title: 'Периодический закон', text: 'Менделеев оставил пустые клетки и написал, каким элементом каждая должна быть. Элементы нашли именно там, где он это предсказал: галлий, скандий, германий.', wiki: 'Периодическая система химических элементов' },
  { kind: 'наука', title: 'Закон Архимеда', text: 'Говорят, он сидел в ванне и закричал «эврика». Что он на самом деле сказал, не знает никто: археологи раскопали водосток, но свидетельств о самом моменте нет.', wiki: 'Закон Архимеда' },
  { kind: 'наука', title: 'Градусники и жара', text: 'Меркурий, спирт и масло расширяются от жара по-разному — на этом и сделан термометр. Но шкала Цельсия появилась позже, а Фаренгейт был немесцем, поэтому градусов «двести» у него — сто на нашем термометре.', wiki: 'Фаренгейт, Данниэль' },
  { kind: 'природа', title: 'Пётр I и грозовой указатель', text: 'Пётр I любил смотреть на грозы из окна. Один из первых в России электрических приборов — «громовой указатель» — был сделан по его указу, чтобы знать заранее, где ударит.', wiki: 'Громовой указатель' },
  { kind: 'литература', title: 'Долгий путь словаря', text: 'Исаак Ломоносов в 1756-м несколько раз писал в манжурском ведомстве, прося о переводе «китайского» текста, — грамматический разбор вместо перевода, которого тогда не умел делать никто.', wiki: 'Ломоносов, Михаил Васильевич' },

  { kind: 'скульптура', title: 'Мрамор, которого почти не было', text: 'Для «Давида» Микеланджело получил в каменоломню пятьдесят блоков — почти все оказались с прожилками. Отсюда дыры в плечах и на спине.', wiki: 'Давид (Микеланджело)' },
  { kind: 'скульптура', title: 'Лошадь Триумфа', text: 'Скульптор Александр Бетховен поставил в Александровском саду памятник покорителю Европы — Наполеону, верхом, с закрытыми глазами: он это сделал в шести версиях.', wiki: 'Александр Бетховен' },
  { kind: 'скульптура', title: 'Рука без тела', text: 'Атлант в Эрмитаже держит небесный свод. Чтобы фигура не выглядела непропорционально, увеличили только ту руку, что на груди.', wiki: 'Атланты Эрмитажа' },
  { kind: 'скульптура', title: 'Ласточка в хвосте', text: 'Знаменитая бронза в Эрмитаже сначала стояла в другом сюжете, но подпись прикрывала её хвост — в балете она внезапно потеряла смысл.', wiki: 'Искусство' },
  { kind: 'здание', title: 'Дом, который отказался разрушаться', text: 'Перед сносом дома в Чикаго его откачали изнутри, расставив подпорки. Сооружение выстояло, хотя должно было рухнуть.', wiki: 'Подпорки' },
  { kind: 'здание', title: 'Окна, которых не видно', text: 'На фасаде одного парижского дома сделали проёмы, но стекла в них не вставили: в центре города аренда выше, чем доход от остеклённых этажей.', wiki: 'Архитектура' },
  { kind: 'здание', title: 'Собор, который никогда не достроили', text: 'Кельнский собор строили семьсот лет и закончили в 1880 году. Тот, кто начинал, не увидел конца.', wiki: 'Кельнский собор' },
  { kind: 'здание', title: 'Танцующий дом', text: 'Особняк в Праге, построенный в 1912 году, называли танцующим домом — из-за волнообразных стен и зелёной черепицы. Заказчик был состоятельным промышленником, а архитектор — учеником великого историка.', wiki: 'Танцующий дом' },
  { kind: 'здание', title: 'Мост из льда', text: 'В Нью-Йорке несколько лет подряд строили ледяной мост через канал, пока однажды он не рухнул вместе с людьми. Потом мост из льда запретили.', wiki: 'Ледяной мост' },
  { kind: 'здание', title: 'Памятник, которого не видно', text: 'Памятник Ходже Насреддину в Ташкенте сделан из двух частей: у входа — тень, на площади — сам поэт. Ночью они совпадают.', wiki: 'Ходжа Насреддин' },
  { kind: 'правитель', title: 'Фёдор Иоаннович', text: 'Последний Рюрикович был набожным и нелюдимым. При нём дворцы простоят ещё сто лет, а Москва примет новых гостей.', wiki: 'Фёдор Иоаннович' },
  { kind: 'правитель', title: 'Баид', text: 'Персидский правитель, который вёл дела через грамотных чиновников, считая их надёжнее самых верных воинов.', wiki: 'Баид' },
  { kind: 'правитель', title: 'Юстиниан I', text: 'Император не умел почти ни одного военного дела и часто проигрывал. Зато при нём появился кодекс, на котором стоит вся юриспруденция.', wiki: 'Юстиниан I' },
  { kind: 'правитель', title: 'Тимур', text: 'Поставил трон в Самарканде и приказал строить мавзолеи, из которых половину разрушили уже в следующем веке.', wiki: 'Тимур' },
  { kind: 'правитель', title: 'Рудольф II', text: 'Император Священной Римской империи тратил деньги на науку и кунсткамеру, а на войны — отчаянно. Оттого Габсбурги и разорились, и оставили после себя музеи.', wiki: 'Рудольф II Габсбург' },
  { kind: 'правитель', title: 'Мухаммад Али', text: 'Правитель Египта ввёл в армии первую современную армию по европейскому образцу — но ввёл и рабский труд, от чего его свергли.', wiki: 'Мухаммад Али-паша' },
  { kind: 'правитель', title: 'Кромвель', text: 'Лорд-протектор правил по военным законам и распустил королевский суд, за что его хоронили насильно, а потом публично — ненадолго.', wiki: 'Кромвель, Оливер' },
  { kind: 'музыка', title: 'Гусиное перо', text: 'Гусёные перья веками использовали для письма и сушки чернил. Одно перо писало остро, но быстро тупилось. Пером пришлось быстро изнашивать, и писали с двух перьев.', wiki: 'Перо (письменность)' },
  { kind: 'композитор', title: 'Крещендо, которое никто не понимал', text: 'Симфония №9 Бетховена заканчивается хором, хотя автор был глух. Текст, который поёт хор, — из «Оды к радости» Шиллера, и он разрешил добавить слова другим.', wiki: 'Симфония №9 (Бетховен)' },
  { kind: 'композитор', title: 'Машина, играющая вальс', text: 'Моцарт и его отец, объезжая Европу, заработали на концертах в пользу заложников. Отец умер в дороге, сыну было 35.', wiki: 'Моцарт, Вольфганг Амадей' },
  { kind: 'композитор', title: 'Проверка слуха', text: 'Моцарт в шестнадцать лет отправлялся слушать орган в Лейпциг и проверял слух. Аккорды, которые он принимал за чужие, оказались знакомыми ему.', wiki: 'Абсолютный слух' },
  { kind: 'композитор', title: 'Случай в Лейпциге', text: 'Моцарт был в городе, где слушали органы лучше в мире, — и ходил проверять свой слух. То, что он считал ошибкой органа, оказалось знакомым ему самим аккордом.', wiki: 'Моцарт, Вольфганг Амадей' },
  { kind: 'композитор', title: 'Рояль, который переехал', text: 'Шопен любил простой инструмент и повозил его на всех своих концертах. Когда его перевезли в Париж, оказалось, что инструмент имеет шкалу, настроенную на треть ниже современной.', wiki: 'Рояль' },
  { kind: 'философ', title: 'Сократ нарочно не записывал', text: 'Он утверждал, что записывание делает речь неподвижной. Ученики передали его слова по памяти — и то, что мы знаем, может быть не совсем им.', wiki: 'Сократ' },
  { kind: 'философ', title: 'Стоики и будильник', text: 'Сенека держал в руках ночью деревянный пейзаж и повторял: «А вот человек не по этой форме, а как существо, способно страдать, ненавидеть и чувствовать».', wiki: 'Сенека' },
  { kind: 'философ', title: 'Диалектика', text: 'Герцен говорил, что его идея родилась из трёх вопросов: откуда взяться человеку, как он живёт и куда идёт.', wiki: 'Герцен, Александр Иванович' },
  { kind: 'философ', title: 'Знаменитое об отсутствии', text: 'Аристотель поставил вопрос: есть ли способ узнать хорошего человека, никогда не сделавшего добра? Двух ответов до сих пор достаточно.', wiki: 'Аристотель' },
  { kind: 'эпоха', title: 'Ренессанс пришёл к банкирам', text: 'Покровителями искусств были семьи Медичи. Их правнучка Мария Медичи стала первой женщиной, имя которой сохранилось в названии парка.', wiki: 'Медичи, семья' },
  { kind: 'эпоха', title: 'Великий перелом', text: 'До середины XVII века в мире было около 450 миллионов человек, через сто — вдвое больше. Это и называют великим ростом.', wiki: 'Демографическая история' },
  { kind: 'наука', title: 'Температура', text: 'Цельсий, Фаренгейт и Реомюр считали температуру по-своему, потому что шкалы изобретались независимо. Пересчёт между ними неудобен.', wiki: 'Шкала Цельсия' },
  { kind: 'наука', title: 'Стекло и радиация', text: 'Обычное стекло не пропускает радиоактивные частицы, поэтому его используют в защитных окнах лабораторий и хранилищ отходов.', wiki: 'Стекло' },
  { kind: 'наука', title: 'Атмосфера, которой почти нет', text: 'В Марсе атмосфера в сто раз тоньше земной. За сто лет работы там не нашли ни капли жидкой воды.', wiki: 'Марс' },
  { kind: 'наука', title: 'Общий предок', text: 'Большинство живых существ делит одну клетку, но каждый организм всё равно хранит собственный геном отдельно.', wiki: 'Геном' },
  { kind: 'наука', title: 'Одна двадцатая', text: 'Солнце излучает около двадцати процентов своей энергии в видимом свете. Остальное — в ультрафиолете, тепле и рентгене.', wiki: 'Солнце' },
  { kind: 'природа', title: 'Озёра, которые не высыхают', text: 'Вода в замкнутых озёрах исчезает от испарения, и многие из них действительно пересыхают. Такие озёра составляют малую долю всех озёр планеты.', wiki: 'Озеро' },
  { kind: 'литература', title: 'Рукописи, которые горят', text: 'Скорость письма на Руси была примерно 30–60 знаков в день. Рукопись на сто страниц — это месяцы работы переписчика.', wiki: 'Древнерусская письменность' },
  { kind: 'литература', title: 'Словарь, который не доделали', text: 'Академический словарь XIX века, который готовили два столетия, в конце концов оставили незавершённым — на букве «О».', wiki: 'Академический словарь' },
  { kind: 'литература', title: 'Писатель, который писал сто лет', text: 'Роман «Война и мир» шёл четыре года и вышел в шести томах, за это время число героев выросло почти вдвое.', wiki: 'Война и мир' },
  { kind: 'музыка', title: 'Волчий хор', text: 'В европейской музыке XVII века ряд полутонов — те самые звуки, которые не согласуются между собой, — называли волчьим хором и считали неприятными. Позже их стали частью гармонии.', wiki: 'Диестес' },
  { kind: 'музыка', title: 'Контрапункт', text: 'Слово пришло из точки «против», откуда вязали противоположные мелодические линии. Сегодня так называют учение о независимом движении голосов.', wiki: 'Контрапункт' },
  { kind: 'театр', title: 'Спектакль на ярмарке', text: 'Театр, который показывал в балагане, давал зрителям то, чего не давал театр придворный: они сидели на ящиках и могли уйти.', wiki: 'Балаган' },
  { kind: 'театр', title: 'Сцена без электричества', text: 'При свечах свет для актёров создавали специальные приёмы — например, смазывали лбы составом, который отражал свечу.', wiki: 'Театральное искусство' },
  { kind: 'кино', title: 'Звук на плёнке', text: 'Первый фильм со звуком — «Песнь о Флате», вышедший в 1927 году. Дорогую плёнку вставляли между звуковыми дорожками.', wiki: 'Флата — певица' },
  { kind: 'кино', title: 'Мультфильм в полнометражке', text: '«Снежная королева» по сказке Андерсена шла четыре года и потребовала около ста тысяч эскизов.', wiki: 'Снежная королева' },
  { kind: 'кино', title: 'Свет и звук по отдельности', text: 'Первый звуковой фильм был снят почти целиком вхолостую, потому что тогда не умели синхронизировать звук с изображением.', wiki: 'Звуковое кино' },
  { kind: 'природа', title: 'Дерево, которого не должно было быть', text: 'Гигантская секвойя была почти навеки забыта, пока её не нашли на склоне, когда там прокладывали дорогу.', wiki: 'Секвойя' },
  { kind: 'наука', title: 'Замедление времени', text: 'Чем быстрее летит тело, тем медленнее для него идёт время. Экспериментально это подтвердили в 1971 году на атомных часах в самолёте.', wiki: 'Замедление времени' },
  { kind: 'наука', title: 'Холодный свет', text: 'Светодиоды изначально стоили столько, что их применяли в приборах, где одна лампа стоила дороже всего прибора. Сейчас это просто лампочка.', wiki: 'Светодиод' },
  { kind: 'наука', title: 'Фрактальный берег', text: 'Береговая линия длиной около километра измерена по-разному — от 100 метров до сотен километров. Чем мельче масштаб, тем длиннее берег.', wiki: 'Фрактал' },
  { kind: 'человек', title: 'Мозг весит больше головы', text: 'Мозг при рождении занимает четверть веса тела и растёт до 24 лет — дольше любого другого органа.', wiki: 'Мозг человека' },
  { kind: 'человек', title: 'Единственная кость не приросла', text: 'Чашеобразная кость, которая крепит мышцы к бедру, не срастается с остальным скелетом. Она подвижна, как и полагается.', wiki: 'Скелет человека' },
  { kind: 'человек', title: 'Отпечатки на руке', text: 'Складки на ладони формируются не от случайных движений, а в утробе, и потом не меняются. Их форма уникальна, как отпечатки пальцев.', wiki: 'Дерматоглифика' },
  { kind: 'общество', title: 'Почему мы зеваем', text: 'Раньше считали, что зевание насыщает мозг кислородом. Тест на компьютере это не подтвердил: зевают и от недостатка кислорода.', wiki: 'Зевание' },
  { kind: 'общество', title: 'Правило на дорогах', text: 'Знаки приоритета в России меняли трижды. Показывать их левой рукой водителям не велено: указатель должен совпадать с рукой.', wiki: 'Дорожные знаки' },
  { kind: 'общество', title: 'Первый телефонный справочник', text: 'В первом справочнике было 22 абонента. Номер состоял из имени, номера адреса и адреса станции — по названию города.', wiki: 'Телефонный справочник' }
];
